class Solution {
public:
    bool canPlaceFlowers(vector<int>& flowerbed, int n) {
        int m = flowerbed.size();
        for (int i = 0; i < m && n > 0; i++) {
            bool leftFree = i == 0 || flowerbed[i - 1] == 0;
            bool rightFree = i == m - 1 || flowerbed[i + 1] == 0;
            if (flowerbed[i] == 0 && leftFree && rightFree) {
                flowerbed[i] = 1;
                n--;
            }
        }
        return n == 0;
    }
};
